        rr=[r for r in gradient if r['group']==group and r['stage']=='INITIAL'];nz=sum(num(r['vertex_gradient_norm'])>1e-12 for r in rr)
        participation.append(dict(group=group,views_expected=8,initial_views_with_actual_nonzero_depth_gradient=nz,endpoint_only_not_every_iteration_certification=True))
